package com.ridex.location.config;
import org.apache.kafka.clients.producer.ProducerConfig; import org.apache.kafka.common.serialization.StringSerializer; import org.junit.jupiter.api.Test; import org.springframework.kafka.core.DefaultKafkaProducerFactory; import org.springframework.test.util.ReflectionTestUtils; import static org.junit.jupiter.api.Assertions.*;
class KafkaProducerConfigTest { @Test void outboxProducerUsesStringSerializers(){KafkaProducerConfig c=new KafkaProducerConfig();ReflectionTestUtils.setField(c,"bootstrapServers","localhost:9092");var f=(DefaultKafkaProducerFactory<String,String>)c.outboxProducerFactory();assertEquals(StringSerializer.class,f.getConfigurationProperties().get(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG));assertEquals(StringSerializer.class,f.getConfigurationProperties().get(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG));} @Test void dltProducerUsesJsonValueSerializer(){KafkaProducerConfig c=new KafkaProducerConfig();ReflectionTestUtils.setField(c,"bootstrapServers","localhost:9092");var f=(DefaultKafkaProducerFactory<String,Object>)c.dltProducerFactory();assertEquals(StringSerializer.class,f.getConfigurationProperties().get(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG));assertEquals(org.springframework.kafka.support.serializer.JsonSerializer.class,f.getConfigurationProperties().get(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG));} }
